//! `table-question-answering`: a table and a question to the answer, generated by TAPEX from the question and the table flattened row by row, as `transformers`' pipeline and `TapexTokenizer` gave it before `transformers` 5 removed the tokenizer.

use std::{
    fmt::{self, Formatter},
    result::Result as StdResult,
};

use serde::{
    Deserialize, Deserializer, Serialize,
    de::{MapAccess, Visitor},
};
use serde_json::Value;

use crate::{
    error::Result,
    head::Seq2SeqLm,
    model,
    processor::text::TextTokenizer,
    source::{LoadOptions, Source},
    task::{Pipeline, seq2seq::Seq2SeqParameters},
};

#[derive(Debug)]
pub struct TableQuestionAnsweringPipeline {
    model: Seq2SeqLm,
    tokenizer: TextTokenizer,
    lowercase: bool,
}

/// A table, its columns in order, each its header and its cells.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Table {
    pub columns: Vec<(String, Vec<String>)>,
}

/// A table in JSON is an object of each column's cells by its header, in the order it lists them, as `pandas.DataFrame` reads one.
impl<'de> Deserialize<'de> for Table {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> StdResult<Self, D::Error> {
        struct TableVisitor;

        impl<'de> Visitor<'de> for TableVisitor {
            type Value = Table;

            fn expecting(&self, formatter: &mut Formatter<'_>) -> fmt::Result {
                formatter.write_str("an object of columns")
            }

            fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> StdResult<Table, A::Error> {
                let mut columns = Vec::new();
                while let Some((header, cells)) = map.next_entry::<String, Vec<Value>>()? {
                    let cells = cells
                        .into_iter()
                        .map(|cell| match cell {
                            Value::String(text) => text,
                            other => other.to_string(),
                        })
                        .collect();
                    columns.push((header, cells));
                }
                Ok(Table { columns })
            }
        }

        deserializer.deserialize_map(TableVisitor)
    }
}

impl Table {
    /// Returns the table as TAPEX reads it: `col : ` and the headers, then each row's `row N : ` and its cells, joined by ` | `.
    #[must_use]
    pub fn linearized(&self) -> String {
        let headers = self
            .columns
            .iter()
            .map(|(header, _)| header.as_str())
            .collect::<Vec<_>>();
        let rows = self
            .columns
            .iter()
            .map(|(_, cells)| cells.len())
            .max()
            .unwrap_or(0);
        let mut text = format!("col : {}", headers.join(" | "));
        text.extend((0..rows).map(|row| {
            let cells = self
                .columns
                .iter()
                .map(|(_, cells)| cells.get(row).map_or("", String::as_str))
                .collect::<Vec<_>>();
            format!(" row {} : {}", row + 1, cells.join(" | "))
        }));
        text
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct TableQuestion {
    pub table: Table,
    pub query: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct TableAnswer {
    pub answer: String,
}

impl Pipeline for TableQuestionAnsweringPipeline {
    type Input = TableQuestion;

    type Parameters = Seq2SeqParameters;

    type Output = TableAnswer;

    fn load(source: &Source, options: LoadOptions) -> Result<Self> {
        let config: Value = source.json("tokenizer_config.json")?;
        Ok(Self {
            model: model::load(source, options)?,
            tokenizer: TextTokenizer::load(source)?,
            lowercase: config["do_lower_case"].as_bool().unwrap_or(false),
        })
    }

    fn run_one(&self, input: &Self::Input, parameters: &Self::Parameters) -> Result<Self::Output> {
        // The question, then the table, lowercased when the tokenizer lowercases.
        let mut text = format!("{} {}", input.query, input.table.linearized());
        if self.lowercase {
            text = text.to_lowercase();
        }

        Ok(TableAnswer {
            answer: self.model.generate_from_text(
                &self.tokenizer,
                &text,
                parameters.max_new_tokens,
                parameters.compile,
            )?,
        })
    }
}
